{"command":"cd /tmp/maze && python3 << 'EOF'
import struct
from collections import deque

with open('archive/data/0', 'rb') as f:
    data = f.read()
vals = struct.unpack('<%df' % (len(data)//4), data)
maze = [[int(vals[i*42+j]) for j in range(42)] for i in range(42)]

start = end = None
for r in range(42):
    for c in range(42):
        if maze[r][c] == 2: start = (r, c)
        if maze[r][c] == 3: end = (r, c)

print("start:", start, "end:", end)

# BFS
prev = {start: None}
q = deque([start])
while q:
    r, c = q.popleft()
    if (r, c) == end:
        break
    for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
        nr, nc = r+dr, c+dc
        if 0 <= nr < 42 and 0 <= nc < 42 and maze[nr][nc] != 1 and (nr,nc) not in prev:
            prev[(nr,nc)] = (r,c)
            q.append((nr,nc))

# reconstruct
path = []
cur = end
while cur is not None:
    path.append(cur)
    cur = prev.get(cur)
path.reverse()
print("path length (nodes):", len(path), "moves:", len(path)-1)

# moves as AWSD: W=up(-1,0), S=down(+1,0), A=left(0,-1), D=right(0,+1)
moves = []
for (r1,c1),(r2,c2) in zip(path, path[1:]):
    if r2 == r1-1: moves.append('W')
    elif r2 == r1+1: moves.append('S')
    elif c2 == c1-1: moves.append('A')
    elif c2 == c1+1: moves.append('D')
pathstr = ''.join(moves)
print("moves:", pathstr)

# count number of distinct shortest paths
import networkx as nx
G = nx.Graph()
for r in range(42):
    for c in range(42):
        if maze[r][c] != 1:
            for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
                nr, nc = r+dr, c+dc
                if 0 <= nr < 42 and 0 <= nc < 42 and maze[nr][nc] != 1:
                    G.add_edge((r,c),(nr,nc))
n_shortest = sum(1 for p in nx.all_shortest_paths(G, start, end))
print("number of distinct shortest paths:", n_shortest)
EOF"}

